-- Pre-seed Knowledge Base Articles
INSERT INTO knowledge_articles (id, title, category, root_cause, content, tags, views, likes, created_at) VALUES
('KB-101', 'Resolving Cisco AnyConnect & GlobalProtect VPN Connection Drops', 'Network', 'VPN server issue / MTU packet fragmentation', 'Step 1: Check VPN gateway status at https://status.internal.net.\nStep 2: Restart Cisco AnyConnect / GlobalProtect client.\nStep 3: Open terminal and flush DNS with ipconfig /flushdns.\nStep 4: If disconnecting repeatedly, lower MTU to 1300.\nStep 5: Contact Network Operations team if problem persists.', 'vpn,network,disconnect,anyconnect,gateway', 342, 88, '2026-09-01 10:00:00'),
('KB-102', 'Troubleshooting Laptop Power and Boot Failures', 'Hardware Issue', 'Power supply or Motherboard failure / Static charge', 'Step 1: Disconnect the AC power adapter.\nStep 2: Disconnect all external USB drives and monitors.\nStep 3: Press and hold down the Power button for 30 consecutive seconds.\nStep 4: Reconnect only the AC power adapter.\nStep 5: Turn on the machine.', 'laptop,hardware,power,boot,black screen', 512, 129, '2026-09-05 11:30:00'),
('KB-103', 'Self-Service Password Reset and Okta MFA Resync Guide', 'Account Access', 'Password expired / locked account / MFA desync', 'Step 1: Navigate to https://login.company.com/sspr.\nStep 2: Verify identity via backup SMS or manager approval.\nStep 3: Set new 14+ character password.\nStep 4: Resync Okta Verify application clock.', 'password,reset,okta,mfa,account', 890, 240, '2026-09-10 09:15:00'),
('KB-104', 'Fixing Docker Desktop WSL2 Kernel and Hyper-V Startup Errors', 'Software Issue', 'WSL2 Linux kernel update package required', 'Step 1: Open PowerShell as Administrator.\nStep 2: Run wsl --update.\nStep 3: Run wsl --set-default-version 2.\nStep 4: Restart computer and launch Docker Desktop.', 'docker,wsl2,software,windows,virtualization', 415, 95, '2026-09-12 14:00:00'),
('KB-105', 'Configuring Dual Monitors on Dell Thunderbolt Docking Stations', 'IT Support', 'Workstation docking configuration / DisplayLink drivers', 'Step 1: Plug Thunderbolt cable into high-power USB-C port.\nStep 2: Connect displays to DisplayPort 1 and HDMI.\nStep 3: Install Dell DisplayLink driver.\nStep 4: Win + P > Extend.', 'monitor,dock,dell,display,setup', 278, 64, '2026-09-15 16:45:00'),
('KB-106', 'Clearing Microsoft Teams and Outlook Local Cache', 'Software Issue', 'Corrupted Teams Electron app cache', 'Step 1: Quit Microsoft Teams.\nStep 2: Win + R > %localappdata%\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Roaming\Microsoft\Teams.\nStep 3: Delete cache files and restart Teams.', 'teams,outlook,cache,crash,microsoft', 620, 175, '2026-09-18 13:20:00')
ON CONFLICT (id) DO NOTHING;
